  "newString": "// === STATE ==============================================================
    let player = { x: 400, y: 300, radius: 5, vx: 0, vy: 0 };
    let hazards = [];
    let score = 0;
    let phase = "menu";
    let keys = new Set();
    // === CONFIG =============================================================
    const W = 800, H = 600;
    const PLAYER_SPEED = 200; // px/sec, optional for auto movement
    const PLAYER_TURN = Math.PI * 1.8; // rad/sec, not used now
    const PLAYER_FRICTION = 0.8; // per second decay factor
    // === RESET =============================================================
    function reset() {
      player.x = W / 2;
      player.y = H / 2;
      player.vx = 0;
      player.vy = 0;
      hazards = [];
      score = 0;
      phase = "playing";
      keys.clear();
      lastTime = performance.now();
      publishState();
      startLoop();
    }
    // === CANVAS =============================================================
    const canvas = document.getElementById('game');
    const ctx = canvas.getContext('2d');
    // === INPUT =============================================================
    const restartBtn = document.getElementById('restart');
    restartBtn.addEventListener('click', reset);
    document.addEventListener('keydown', (ev) => {
      if (ev.key === 'r' || ev.key === 'R') {
        reset();
        return;
      }
      keys.add(ev.key);
      if (ev.key === ' ') ev.preventDefault();
    });
    document.addEventListener('keyup', (ev) => {
      keys.delete(ev.key);
    });
    // === LOOP =============================================================
    let loopId = null;
    let lastTime = performance.now();
    function startLoop() {
      if (loopId !== null) cancelAnimationFrame(loopId);
      function tick(now) {
        try {
          const dt = Math.min((now - lastTime) / 1000, 0.1);
          lastTime = now;
          update(dt);
          render();
          publishState();
        } catch (err) {
          console.error('loop error', err);
        }
        loopId = requestAnimationFrame(tick);
      }
      loopId = requestAnimationFrame(tick);
    }
    // === UPDATE =============================================================
    function update(dt) {
      if (phase !== "playing") return;
      // Simple auto-forward movement (to the right) for demo
      player.x += PLAYER_SPEED * dt;
      // Wrap around
      if (player.x > W) player.x -= W;
      // TODO: handle keys for pulse etc.
    }
    // === RENDER =============================================================
    function render() {
      // Clear canvas
      ctx.fillStyle = '#05050c';
      ctx.fillRect(0, 0, W, H);
      // Draw player
      ctx.fillStyle = '#7df9ff';
      ctx.beginPath();
      ctx.arc(player.x, player.y, player.radius, 0, Math.PI * 2);
      ctx.fill();
      // Draw HUD (score)
      ctx.fillStyle = '#e6e6f0';
      ctx.font = '16px ui-sans-serif, system-ui';
      ctx.textAlign = 'left';
      ctx.fillText(`Score ${score}`, 12, 22);
    }
    // === AUDIO =============================================================
    let audioCtx = null;
    function beep(freq, durSec) {
      try {
        if (!audioCtx) audioCtx = new (window.AudioContext || window.webkitAudioContext)();
        const osc = audioCtx.createOscillator();
        const gain = audioCtx.createGain();
        osc.type = 'triangle';
        osc.frequency.value = freq;
        gain.gain.setValueAtTime(0.04, audioCtx.currentTime);
        gain.gain.exponentialRampToValueAtTime(0.001, audioCtx.currentTime + durSec);
        osc.connect(gain);
        gain.connect(audioCtx.destination);
        osc.start();
        osc.stop(audioCtx.currentTime + durSec);
      } catch (e) {}
    }
    // === OBSERVABLE CONTRACT ===============================================
    function publishState() {
      window.__game = {
        state: phase,
        score: score,
        player: {
          x: player.x,
          y: player.y,
          visible: player.x >= 0 && player.x < W && player.y >= 0 && player.y < H,
        },
        objective: "Tap to pulse and avoid obstacles.",
      };
    }
    // === BOOT =============================================================
    reset();"
